function productDefaults(){defaults({target:4,selected:state.habits[0]?.id||'',notes:[]})}
function productRender(){const days=Array.from({length:14},(_,i)=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-13+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}),week=days.slice(-7);const h=state.habits.find(x=>x.id===p.selected)||state.habits[0];put(`<div class="grid"><div>${box('近两周的行动足迹',`<form id="habit-target" class="fields"><label>观察哪个习惯<select name="selected">${state.habits.map(x=>`<option value="${x.id}" ${h?.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${field('滚动七天目标次数','target','number',p.target,'required min="1" max="7"')}<button>保存目标</button></form><div class="calendar-grid" style="margin-top:20px">${days.map(d=>`<div class="day-cell ${(state.logs[d]||[]).includes(h?.id)?'done':''}">${d.slice(5)}<br>${(state.logs[d]||[]).includes(h?.id)?'✓':'·'}</div>`).join('')}</div><p>最近七天完成 ${week.filter(d=>(state.logs[d]||[]).includes(h?.id)).length} / ${p.target} 次。空白只是记录状态，不是失败。</p>`)}${box('调整习惯',`<form id="edit-habit" class="stack"><label>要调整的习惯<select name="id">${state.habits.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>${field('新名称','name','text','','required maxlength="40"')}${field('提醒线索','reminder','text','','required maxlength="80"')}<button>保存修改</button></form>${state.habits.map(x=>`<div class="item"><span>${esc(x.name)}</span><button data-remove="${x.id}" class="small">移除习惯与打卡</button></div>`).join('')}`)}</div><div>${box('把经验写下来',`<form id="habit-note" class="stack">${field('什么提醒最有帮助','note','text','','required maxlength="150"')}<button>保存发现</button></form>${rows(p.notes,x=>`<div class="item"><div>${x.date}<p>${esc(x.note)}</p></div></div>`)}`,'tint')}${box('导出行动记录',btn('导出打卡 CSV','habit-csv',''))}</div></div>`);form('habit-target',v=>{p.selected=v.selected;p.target=+v.target;commit()});form('edit-habit',v=>{const x=state.habits.find(x=>x.id===v.id);if(x)Object.assign(x,v);commit()});deleteButtons('remove',id=>{if(state.habits.length===1)return toast('至少保留一个习惯');state.habits=state.habits.filter(x=>x.id!==id);for(const d in state.logs)state.logs[d]=state.logs[d].filter(x=>x!==id);commit()});form('habit-note',v=>{p.notes.push({...v,date:today()});commit()});on('habit-csv',()=>exportCSV('打卡记录.csv',['日期','习惯'],Object.entries(state.logs).flatMap(([d,ids])=>ids.map(id=>[d,state.habits.find(x=>x.id===id)?.name||'已移除']))))}
